// Prepares everything the browser needs to run code and to edit it, and writes it to public/vendor/.
//   npm run vendor            (from the project root)
//
// The output is committed to git, so a deployment never has to run this script.
//   pyodide/       Python (CPython compiled to WebAssembly)
//   clang/         C++ compiler (clang + lld + libc++ compiled to WebAssembly), split in gzip parts because one
//                  static file may be at most 25 MiB on Cloudflare Workers
//   wasi/shim.js   runs the compiled C++ programs (a WASI implementation for the browser)
//   codemirror/    the code editor
//   THIRD_PARTY.md the licenses of all of the above

import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const OUT = path.resolve(HERE, '../../public/vendor');
const NM = path.join(HERE, 'node_modules');
const PART_BYTES = 20 * 1024 * 1024;   // raw bytes per part; a part is gzip-compressed on disk

const read = (p) => fs.readFileSync(p);
const write = (rel, data) => { const f = path.join(OUT, rel); fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, data); return f; };
const mb = (n) => (n / 1048576).toFixed(1) + ' MB';
const pkg = (name) => JSON.parse(read(path.join(NM, name, 'package.json')).toString());

fs.rmSync(OUT, { recursive: true, force: true });

// ---- Python ----
for (const f of ['pyodide.mjs', 'pyodide.asm.mjs', 'pyodide.asm.wasm', 'python_stdlib.zip', 'pyodide-lock.json']) {
  write('pyodide/' + f, read(path.join(NM, 'pyodide', f)));
}
console.log('pyodide: copied');

// ---- C++ ----
const clangDir = path.join(NM, '@yowasp/clang/gen');
write('clang/bundle.js', read(path.join(clangDir, 'bundle.js')));
for (const f of ['llvm.core2.wasm', 'llvm.core3.wasm', 'llvm.core4.wasm']) write('clang/' + f, read(path.join(clangDir, f)));

const manifest = {};
for (const name of ['llvm.core.wasm', 'llvm-resources.tar']) {
  const data = read(path.join(clangDir, name));
  const parts = [];
  for (let i = 0, n = 0; i < data.length; i += PART_BYTES, n++) {
    const gz = zlib.gzipSync(data.subarray(i, i + PART_BYTES), { level: 9 });
    const file = `${name}.${n}.gz`;
    write('clang/' + file, gz);
    parts.push({ file, bytes: gz.length });
  }
  manifest[name] = { size: data.length, parts };
  console.log(`clang: ${name} ${mb(data.length)} -> ${parts.length} parts, ${mb(parts.reduce((a, p) => a + p.bytes, 0))} compressed`);
}
write('clang/manifest.json', JSON.stringify(manifest, null, 1));

// ---- WASI shim and the editor ----
await build({
  entryPoints: [path.join(NM, '@bjorn3/browser_wasi_shim/dist/index.js')],
  bundle: true, format: 'esm', minify: true, target: 'es2022', outfile: path.join(OUT, 'wasi/shim.js'), legalComments: 'none'
});
await build({
  entryPoints: [path.join(HERE, 'cm-entry.js')],
  bundle: true, format: 'esm', minify: true, target: 'es2022', outfile: path.join(OUT, 'codemirror/editor.js'), legalComments: 'none'
});
console.log('wasi shim and editor bundled');

// ---- licenses (read from each package, never typed by hand) ----
const used = [
  ['pyodide', 'Python in the browser'],
  ['@yowasp/clang', 'C++ compiler in the browser (LLVM, Clang, LLD, libc++)'],
  ['@bjorn3/browser_wasi_shim', 'runs compiled C++ programs'],
  ['@codemirror/state', 'code editor'], ['@codemirror/view', 'code editor'], ['@codemirror/commands', 'code editor'],
  ['@codemirror/language', 'code editor'], ['@codemirror/autocomplete', 'code editor'],
  ['@codemirror/lang-cpp', 'code editor'], ['@codemirror/lang-python', 'code editor'], ['@codemirror/lang-java', 'code editor'],
  ['@lezer/highlight', 'code editor']
];
const rows = used.map(([n, what]) => { const p = pkg(n); return `| ${n} | ${p.version} | ${typeof p.license === 'string' ? p.license : JSON.stringify(p.license)} | ${what} |`; });
write('THIRD_PARTY.md', [
  '# Third-party software in public/vendor',
  '',
  'These files are generated by `npm run vendor` (see tools/vendor/build.mjs). Each package keeps its own license.',
  '',
  '| Package | Version | License | Used for |',
  '|---|---|---|---|',
  ...rows,
  '',
  '## Not bundled',
  '',
  'CheerpJ 5 (Java in the browser) is not part of these files. The Java sandbox (the java/ folder, a separate Worker) loads it at run',
  'time from https://cjrtnc.leaningtech.com. It is used under CheerpJ\'s free Community license for individuals and non-commercial',
  'open source, which asks for the credit "Built with CheerpJ"; the credit is shown in the sidebar of the site. See https://cheerpj.com/licensing/.',
  ''
].join('\n'));

const total = (function sum(d) { return fs.readdirSync(d, { withFileTypes: true }).reduce((a, e) => a + (e.isDirectory() ? sum(path.join(d, e.name)) : fs.statSync(path.join(d, e.name)).size), 0); })(OUT);
console.log('done. public/vendor is', mb(total));
